arguments.new_str:
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(storageRootPath: "eval-results");
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static IEnumerable<IEvaluator> GetEvaluators()
    {
        yield return new CoherenceEvaluator();
        yield return new RelevanceEvaluator();
        yield return new FluencyEvaluator();
        yield return new GroundednessEvaluator();
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                TestContext.FullyQualifiedTestClassName!,
                TestContext.TestName!);

        var builder = DistributedApplication.CreateBuilder();
        var chatClient = builder.AddAzureOpenAIChatClient("chat", "gpt-4o-mini");

        // Use a test chat client for evaluation
        IChatClient evaluatorChatClient = scenario.ChatConfiguration.ChatClient
            ?? throw new InvalidOperationException("No chat client configured for evaluation.");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await evaluatorChatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));

        var evalResponse = new EvaluationResponse(messages, response.Text);

        await scenario.EvaluateAsync(evalResponse, GetEvaluators());
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndFluent()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                TestContext.FullyQualifiedTestClassName!,
                TestContext.TestName!);

        IChatClient evaluatorChatClient = scenario.ChatConfiguration.ChatClient
            ?? throw new InvalidOperationException("No chat client configured for evaluation.");

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await evaluatorChatClient.GetResponseAsync(messages);
        messages.Add(new ChatMessage(ChatRole.Assistant, response.Text));

        var evalResponse = new EvaluationResponse(messages, response.Text, context: "The capital of France is Paris.");

        await scenario.EvaluateAsync(evalResponse, GetEvaluators());
    }

    public TestContext TestContext { get; set; } = null!;
}

