using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    public TestContext TestContext { get; set; } = null!;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var chatConfig = new ChatConfiguration(new ChatClientBuilder()
            .UseFunctionInvocation()
            .Use(new OllamaChatClient(new Uri("http://localhost:11434"), "llama3.2")));

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators: GetEvaluators(),
            chatConfiguration: chatConfig);
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    private static IEnumerable<IEvaluator> GetEvaluators()
