 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

 namespace MyApp.Evals;

 [TestClass]
 public sealed class ChatEvals
 {
     private static ReportingConfiguration? s_reportingConfiguration;

     public TestContext TestContext { get; set; } = null!;

     [AssemblyInitialize]
     public static void Initialize(TestContext context)
     {
         IChatClient chatClient =
             new OllamaChatClient(new Uri("http://localhost:11434"), "llama3.2");

         var chatConfig = new ChatConfiguration(chatClient);

         s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
             storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
             evaluators: GetEvaluators(),
             chatConfiguration: chatConfig);
     }

     [AssemblyCleanup]
     public static void Cleanup()
     {
     }

     private static IEnumerable<IEvaluator> GetEvaluators()
     {
         yield return new CoherenceEvaluator();
         yield return new RelevanceEvaluator();
         yield return new FluencyEvaluator();
         yield return new GroundednessEvaluator();
     }

     [TestMethod]
     public async Task GreetingResponse_IsCoherentAndRelevant()
     {
         await using ScenarioRun scenario =
             await s_reportingConfiguration!.CreateScenarioRunAsync(
                 TestContext.FullyQualifiedTestClassName!,
                 TestContext.TestName!);

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Hello, how can you help me today?")
         };

         ChatResponse response =
             await scenario.ChatConfiguration!.ChatClient!.GetResponseAsync(messages);

         await scenario.EvaluateAsync(messages, response);
     }

     [TestMethod]
     public async Task FactualQuestion_IsGroundedAndFluent()
     {
         await using ScenarioRun scenario =
             await s_reportingConfiguration!.CreateScenarioRunAsync(
                 TestContext.FullyQualifiedTestClassName!,
                 TestContext.TestName!);

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         ChatResponse response =
             await scenario.ChatConfiguration!.ChatClient!.GetResponseAsync(messages);

         var groundingContext = new GroundednessEvaluatorContext("The capital of France is Paris.");

         await scenario.EvaluateAsync(messages, response, [groundingContext]);
     }
 }

